"""Function to false negative

    Arguments:
        y_true {list} -- list of true values
        y_pred {list} -- list of predicted values
    """
def false_negative(y_true: Any, y_pred: Any) -> object {
    fn = 0;
    for (yt, yp) in zip(y_true, y_pred) {
        if ((yt == 1) and (yp == 0)) {
            fn += 1;
        }
    }
    return fn;
}

"""Given a block of source lines for a method or function,
    get the lines for the function block.
    """
def get_func_definition(sourcelines: Any) -> object {
    count = 1;
    for line in sourcelines {
        if line.rstrip().endswith(':') {
            break;
        }
        count += 1;
    }
    return (sourcelines[:count], sourcelines[count:]);
}

"""
    Remove the top item from a heap with
    count items and restore its heap property.
    """
def remove_top_item(values: Any, count: Any) -> object {
    result = values[0];
    values[0] = values[(count - 1)];
    index = 0;
    while True {
        child1 = (2 * index) + 1;
        child2 = (2 * index) + 2;
        if (child1 >= count) {
            child1 = index;
        }
        if (child2 >= count) {
            child2 = index;
        }
        if ((values[index] >= values[child1]) and (values[index] >= values[child2])) {
            break;
        }
        if (values[child1] > values[child2]) {
            swap_child = child1;
        } else {
            swap_child = child2;
        }
        (values[index], values[swap_child]) = (values[swap_child], values[index]);
        index = swap_child;
    }
    return result;
}

"""
    Determine a mesh output format based on a file name.

    Determine a mesh output format based on a file name. This inspects the file extension.

    Parameters
    ----------
    filename: string
        A file name, may start with a full path. Examples: 'brain.obj' or '/home/myuser/export/brain.ply'. If the file extension is not a recognized extension for a supported format, the default format 'obj' is returned.

    Returns
    -------
    format: string
        A string defining a supported mesh output format. One of ('ply', 'obj').

    matched: Boolean
        Whether the file name ended with a known extension. If not, the returned format was chosen because it is the default format.
    """
def _mesh_export_format_from_filename(filename: Any) -> object {
    if filename.endswith('.ply') {
        return ('ply', True);
    } elif filename.endswith('.obj') {
        return ('obj', True);
    } else {
        return ('obj', False);
    }
}

""" Given a list of names, some of the names can be comma-separated lists.
        Return a new list of single names (names in comma-separated lists are
        spliced into the list).
    """
def _splice_comma_names(namelist: Any) -> object {
    newlist = [];
    for name in namelist {
        if (',' in name) {
            newlist.extend(name.split(','));
        } else {
            newlist.append(name);
        }
    }
    return newlist;
}

